-- Paisa OS 009: many more default categories and subcategories (expenses and income).
-- Additive only: adds any category / subcategory a book doesn't have yet. Existing ones (and the
-- transactions in them) are untouched; matching is by name, case-insensitive.

do $$
declare
  tree jsonb := '[{"class":"expense","name":"Food","icon":"🍲","sort":0,"subs":["Groceries","Ration & staples","Vegetables & fruits","Milk & dairy","Meat, fish & eggs","Bakery & sweets","Drinking water","Dining out","Delivery","Snacks & coffee","Office meals"],"not_income":false},{"class":"expense","name":"Household help","icon":"🧑‍🍳","sort":1,"subs":["Cook","Maid","Cleaning","Laundry & ironing","Driver","Babysitter & nanny","Gardener","Security & watchman"],"not_income":false},{"class":"expense","name":"Housing","icon":"🏠","sort":2,"subs":["Rent","Maintenance","Electricity","Internet","Water & gas","Cooking gas (LPG)","Repairs & services","Furniture & furnishing","Appliances","Home decor","Pest control","Property tax","Brokerage & deposit"],"not_income":false},{"class":"expense","name":"Transport","icon":"🛵","sort":3,"subs":["Fuel","Cab & auto","Public transport","Parking & tolls","Vehicle service","Train","Bike & car rental","FASTag recharge"],"not_income":false},{"class":"expense","name":"Vehicle","icon":"🚗","sort":4,"subs":["Insurance","Spare parts & tyres","Accessories","Washing & detailing","Fines & challans","PUC & registration","Road tax"],"not_income":false},{"class":"expense","name":"Shopping","icon":"🛍️","sort":5,"subs":["Apparel","Footwear","Accessories","Jewellery","Electronics","Household","Home & kitchen","Gifts given","Stationery","Online orders"],"not_income":false},{"class":"expense","name":"Bills & subscriptions","icon":"🧾","sort":6,"subs":["Mobile","Subscriptions","Insurance","DTH & cable TV","OTT streaming","Music streaming","Cloud & software","News & magazines"],"not_income":false},{"class":"expense","name":"Health","icon":"🩺","sort":7,"subs":["Doctor","Medicines","Fitness","Medical tests & scans","Hospital","Dental","Eye care","Therapy & counselling","Physiotherapy","Vaccines","Supplements","Health insurance"],"not_income":false},{"class":"expense","name":"Personal care","icon":"💈","sort":8,"subs":["Salon & grooming","Skincare","Cosmetics","Spa & massage","Toiletries"],"not_income":false},{"class":"expense","name":"Entertainment","icon":"🎬","sort":9,"subs":["Movies & events","Games","Outings","Concerts & shows","Sports events","Adventure & activities"],"not_income":false},{"class":"expense","name":"Education","icon":"📚","sort":10,"subs":["Courses","Books","School fees","College fees","Coaching & tuition","Exam fees","Online learning","Stationery & supplies"],"not_income":false},{"class":"expense","name":"Travel","icon":"✈️","sort":11,"subs":["Flights & trains","Stays","Local travel","Visa & passport","Travel insurance","Food on trips","Sightseeing","Forex & card fees"],"not_income":false},{"class":"expense","name":"Family","icon":"👪","sort":12,"subs":["Parents","Siblings","Partner","Relatives","Elder care"],"not_income":false},{"class":"expense","name":"Kids","icon":"🧸","sort":13,"subs":["Daycare","School supplies","Toys","Clothes","Activities & classes","Baby care"],"not_income":false},{"class":"expense","name":"Pets","icon":"🐾","sort":14,"subs":["Pet food","Vet","Grooming","Pet supplies"],"not_income":false},{"class":"expense","name":"Social life","icon":"🍻","sort":15,"subs":["Parties","Drinks","Treats for friends","Dates"],"not_income":false},{"class":"expense","name":"Gifts & occasions","icon":"🎁","sort":16,"subs":["Birthdays","Weddings","Festivals","Anniversaries"],"not_income":false},{"class":"expense","name":"Hobbies","icon":"🎨","sort":17,"subs":["Sports & gear","Music","Photography","Gaming","Arts & crafts"],"not_income":false},{"class":"expense","name":"Religious & charity","icon":"🪔","sort":18,"subs":["Donations","Temple & worship","Pooja items","Religious events"],"not_income":false},{"class":"expense","name":"Work","icon":"💼","sort":19,"subs":["Office supplies","Co-working","Professional fees","Work travel","Memberships"],"not_income":false},{"class":"expense","name":"Fees & charges","icon":"🏦","sort":20,"subs":["Bank charges","Interest paid","Late fees","Card annual fee","Processing fees","Convenience fees","Brokerage"],"not_income":false},{"class":"expense","name":"Taxes","icon":"🧮","sort":21,"subs":["Income tax","Advance tax","GST","Professional tax"],"not_income":false},{"class":"expense","name":"Other","icon":"•","sort":22,"subs":[],"not_income":false},{"class":"income","name":"Salary","icon":"💼","sort":0,"subs":["Bonus","Incentive & commission","Arrears","Leave encashment"],"not_income":false},{"class":"income","name":"Business & freelance","icon":"🧑‍💻","sort":1,"subs":["Freelance","Consulting","Business income","Side projects"],"not_income":false},{"class":"income","name":"Interest","icon":"🏦","sort":2,"subs":["Savings interest","FD interest","RD interest","Bond interest"],"not_income":false},{"class":"income","name":"Dividends","icon":"📈","sort":3,"subs":[],"not_income":false},{"class":"income","name":"Capital gains","icon":"📊","sort":4,"subs":["Stocks","Mutual funds","Property","Gold"],"not_income":false},{"class":"income","name":"Rental income","icon":"🏘️","sort":5,"subs":["House rent","Other rent"],"not_income":false},{"class":"income","name":"Pension","icon":"👵","sort":6,"subs":[],"not_income":false},{"class":"income","name":"Other income","icon":"•","sort":7,"subs":["Prizes & winnings","Royalties"],"not_income":false},{"class":"income","name":"Refunds & cashback","icon":"↩️","sort":8,"subs":["Refunds","Cashback & rewards"],"not_income":true},{"class":"income","name":"Gifts received","icon":"🎁","sort":9,"subs":["Cash gifts","Shagun"],"not_income":true},{"class":"income","name":"Money in (not income)","icon":"📥","sort":10,"subs":["Repayments","From family","Reimbursements","Sold something","Deposit returned","Insurance claims","Other money in"],"not_income":true}]';
  b record; p jsonb; c text; pid uuid; j int; meta jsonb;
begin
  for b in select id from book loop
    for p in select * from jsonb_array_elements(tree) loop
      meta := case when (p->>'not_income')::boolean then '{"not_income": true}'::jsonb else '{}'::jsonb end;
      select id into pid from account
       where book_id = b.id and kind = 'category' and class = (p->>'class')::account_class and parent_id is null and lower(name) = lower(p->>'name');
      if pid is null then
        insert into account (book_id, class, kind, name, icon, sort, meta)
        values (b.id, (p->>'class')::account_class, 'category', p->>'name', p->>'icon', (p->>'sort')::int, meta)
        returning id into pid;
      end if;
      j := 0;
      for c in select jsonb_array_elements_text(p->'subs') loop
        if not exists (select 1 from account where book_id = b.id and kind = 'category' and parent_id = pid and lower(name) = lower(c)) then
          insert into account (book_id, class, kind, name, parent_id, sort, meta)
          values (b.id, (p->>'class')::account_class, 'category', c, pid, j, meta);
        end if;
        j := j + 1;
      end loop;
    end loop;
  end loop;
end $$;
